import React, { useState } from 'react';

function SeatScreen({ showtime, movie, rooms, seats, bookings, onSeatsSelected, onBack }) {
  const [selectedSeats, setSelectedSeats] = useState([]);

  const isSeatBooked = (seatId) => bookings.some(b => b.showtime_id === showtime.id && b.seat_id === seatId);

  const currentRoom = rooms.find((room) => room.id === showtime.room_id) || {};
  const isVipRoom = currentRoom.is_vip === true;
  const actualTicketPrice = showtime.ticket_price + (isVipRoom ? 50000 : 0);

  const getSeatRow = (seatNumber) => {
    const match = seatNumber.match(/^([A-Za-z]+)/);
    return match ? match[1].toUpperCase() : '';
  };

  const getSeatIndex = (seatNumber) => {
    const match = seatNumber.match(/(\d+)$/);
    return match ? Number(match[1]) : 0;
  };

  const roomSeats = seats.filter(seat => seat.room_id === showtime.room_id);

  const sortedSeats = [...roomSeats].sort((a, b) => {
    const rowA = getSeatRow(a.seat_number);
    const rowB = getSeatRow(b.seat_number);
    if (rowA !== rowB) return rowA.localeCompare(rowB);
    return getSeatIndex(a.seat_number) - getSeatIndex(b.seat_number);
  });

  const seatRows = sortedSeats.reduce((acc, seat) => {
    const row = getSeatRow(seat.seat_number);
    if (!acc[row]) acc[row] = [];
    acc[row].push(seat);
    return acc;
  }, {});

  const selectedTotal = selectedSeats.length * actualTicketPrice;

  const handleSeatClick = (seat) => {
    if (isSeatBooked(seat.id)) return;
    if (selectedSeats.includes(seat.id)) {
      setSelectedSeats(selectedSeats.filter(id => id !== seat.id));
    } else {
      setSelectedSeats([...selectedSeats, seat.id]);
    }
  };

  const handleConfirm = () => {
    if (selectedSeats.length === 0) {
      alert("Vui lòng chọn ít nhất 1 ghế trước khi bấm xác nhận!");
      return;
    }
    alert(`🎉 Đặt vé thành công! Bạn đã chọn ${selectedSeats.length} ghế.`);
    
    onSeatsSelected({
      showtime_id: showtime.id,
      movie_id: movie.id,
      seat_ids: selectedSeats,
      ticketTotal: selectedTotal
    });
    setSelectedSeats([]);
  };

  return (
    <div style={{ color: '#e2e8f0', minHeight: '80vh' }}>
      <button
        className="btn mb-4 fw-bold text-white border-0"
        style={{
          background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)',
          boxShadow: '0 18px 30px rgba(124, 58, 237, 0.30)'
        }}
        onClick={onBack}
      >⬅ Quay lại suất chiếu</button>
      
      <div className="row">
        <div className="col-md-8 mb-4">
          <div
            className="card p-4 shadow-sm border-0 text-center"
            style={{
              background: 'rgba(15, 23, 42, 0.94)',
              border: '1px solid rgba(79, 70, 229, 0.18)'
            }}
          >
            <div
              className="py-2 mb-5 rounded fw-bold shadow-sm"
              style={{
                letterSpacing: '4px',
                background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)',
                color: 'white'
              }}
            >🎬 MÀN HÌNH CHIẾU</div>
            
            <div className="mx-auto" style={{ width: '100%', overflowX: 'auto' }}>
              {Object.keys(seatRows).map((row) => (
                <div key={row} className="d-flex align-items-center mb-3" style={{ gap: '16px' }}>
                  <div className="fw-bold" style={{ minWidth: '24px', color: '#cbd5e1' }}>{row}</div>
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(10, 75px)', justifyContent: 'center', gap: '12px' }}>
                    {seatRows[row].map(seat => {
                      const booked = isSeatBooked(seat.id);
                      const selected = selectedSeats.includes(seat.id);
                      
                      let btnClass = 'btn fw-bold';
                      let btnStyle = {
                        width: '65px',
                        height: '55px',
                        backgroundColor: 'rgba(15, 23, 42, 0.92)',
                        color: '#e2e8f0',
                        border: '1px solid rgba(148, 163, 184, 0.18)'
                      };
                      if (booked) {
                        btnClass = 'btn fw-bold disabled text-white';
                        btnStyle = {
                          ...btnStyle,
                          background: 'linear-gradient(135deg, #a855f7 0%, #ec4899 100%)',
                          color: 'white',
                          border: '1px solid rgba(236, 72, 153, 0.45)',
                          cursor: 'not-allowed'
                        };
                      }
                      if (selected) {
                        btnClass = 'btn fw-bold text-white shadow';
                        btnStyle = {
                          ...btnStyle,
                          background: 'linear-gradient(135deg, #facc15 0%, #f97316 100%)',
                          color: '#0f172a',
                          border: '1px solid rgba(250, 204, 21, 0.45)'
                        };
                      }

                      return (
                        <button key={seat.id} className={btnClass} style={btnStyle} onClick={() => handleSeatClick(seat)}>
                          {seat.seat_number}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>

            <div className="d-flex justify-content-center gap-4 mt-5 border-top pt-3 small fw-bold" style={{ color: '#94a3b8' }}>
              <div><span className="badge me-1" style={{ width: '15px', height: '15px', backgroundColor: '#475569' }}> </span> Trống</div>
              <div><span className="badge me-1" style={{ width: '15px', height: '15px', backgroundColor: '#facc15' }}> </span> Đang chọn</div>
              <div><span className="badge me-1" style={{ width: '15px', height: '15px', backgroundColor: '#ec4899' }}> </span> Đã đặt</div>
            </div>
          </div>
        </div>

        <div className="col-md-4">
          <div
            className="card p-4 shadow-sm border-0 sticky-top"
            style={{
              top: '20px',
              background: 'rgba(15, 23, 42, 0.94)',
              border: '1px solid rgba(79, 70, 229, 0.18)'
            }}
          >
            <h4 className="fw-bold border-bottom pb-2" style={{ color: '#e2e8f0' }}>Thông Tin Đặt Vé</h4>
            <div className="mb-3 mt-2" style={{ color: '#cbd5e1' }}>Phim: <strong className="fs-5 d-block" style={{ color: '#f472b6' }}>{movie.title}</strong></div>
            <div className="mb-2" style={{ color: '#cbd5e1' }}>Suất Chiếu: <strong style={{ color: '#e2e8f0' }}>{showtime.show_time} | {showtime.show_date}</strong></div>
            <div className="mb-4" style={{ color: '#cbd5e1' }}>Số lượng ghế: <strong className="badge fs-6" style={{ backgroundColor: 'rgba(124, 58, 237, 0.18)', color: '#e2e8f0' }}>{selectedSeats.length} ghế</strong></div>
            
            <div className="border-top pt-3 d-flex justify-content-between align-items-center">
              <span className="fw-bold" style={{ color: '#cbd5e1' }}>Tổng Vé:</span>
              <h3 className="fw-bold m-0" style={{ color: '#facc15' }}>{selectedTotal.toLocaleString()}đ</h3>
            </div>
            <div className="small mt-2" style={{ color: '#94a3b8' }}>
              Giá mỗi ghế: {actualTicketPrice.toLocaleString()}đ{isVipRoom ? ' (Phòng VIP +50.000đ)' : ''}
            </div>
            
            <button
              className="btn w-100 fw-bold mt-4 py-3 fs-5 shadow text-white border-0"
              style={{
                background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)'
              }}
              onClick={handleConfirm}
            >✓ XÁC NHẬN ĐẶT VÉ</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default SeatScreen;
